using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capability to the research agent.
/// Uses the Brave Search API for web queries.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<WebSearchTool> _logger;

    public WebSearchTool(HttpClient httpClient, ILogger<WebSearchTool> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    [Description("Searches the web for information on a given query. Returns a list of relevant results with titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to find information about")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5,
        CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(query))
        {
            return "Error: Search query cannot be empty.";
        }

        maxResults = Math.Clamp(maxResults, 1, 10);

        _logger.LogInformation("Searching web for: {Query} (max {MaxResults} results)", query, maxResults);

        try
        {
            var request = new HttpRequestMessage(HttpMethod.Get,
                $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}");

            var apiKey = Environment.GetEnvironmentVariable("BRAVE_SEARCH_API_KEY");
            if (string.IsNullOrEmpty(apiKey))
            {
                // Fallback: return simulated results for demo purposes
                return GetSimulatedResults(query, maxResults);
            }

            request.Headers.Add("Accept", "application/json");
            request.Headers.Add("X-Subscription-Token", apiKey);

            var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadAsStringAsync(cancellationToken);
            return ParseSearchResults(json, maxResults);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Web search failed, returning simulated results");
            return GetSimulatedResults(query, maxResults);
        }
    }

    private static string ParseSearchResults(string json, int maxResults)
    {
        using var doc = JsonDocument.Parse(json);
        var results = new List<string>();

        if (doc.RootElement.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var webResults))
        {
            foreach (var result in webResults.EnumerateArray().Take(maxResults))
            {
                var title = result.GetProperty("title").GetString();
                var url = result.GetProperty("url").GetString();
                var description = result.TryGetProperty("description", out var desc)
                    ? desc.GetString() : "No description available";

                results.Add($"- **{title}**\n  URL: {url}\n  {description}");
            }
        }

        return results.Count > 0
            ? string.Join("\n\n", results)
            : "No results found.";
    }

    private static string GetSimulatedResults(string query, int maxResults)
    {
        // Simulated results for demonstration when no API key is configured
        var results = new List<string>
        {
            $"- **{query} - Overview and Key Concepts**\n  URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}\n  A comprehensive overview of {query} covering history, current state, and future directions.",
            $"- **Latest Research on {query}**\n  URL: https://research.example.com/{Uri.EscapeDataString(query)}\n  Recent studies and findings related to {query}, including breakthroughs and ongoing investigations.",
            $"- **{query}: A Practical Guide**\n  URL: https://guide.example.com/{Uri.EscapeDataString(query)}\n  Step-by-step guide covering practical applications and best practices for {query}.",
            $"- **The Future of {query}**\n  URL: https://future.example.com/{Uri.EscapeDataString(query)}\n  Expert predictions and emerging trends related to {query} for the coming years.",
            $"- **{query} - Industry Impact and Analysis**\n  URL: https://analysis.example.com/{Uri.EscapeDataString(query)}\n  In-depth analysis of how {query} is transforming industries and creating new opportunities."
        };

        return string.Join("\n\n", results.Take(maxResults));
    }
}

using System.ComponentModel;
using System.Text;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capability for the research agent to organize findings.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<ResearchNote> _notes = [];
    private readonly ILogger<NoteTakingTool> _logger;

    public NoteTakingTool(ILogger<NoteTakingTool> logger)
    {
        _logger = logger;
    }

    [Description("Saves a research note with a title and content. Use this to record key findings, facts, and insights discovered during research.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The content of the note — key findings, facts, or insights")] string content,
        [Description("Optional source URL where the information was found")] string? sourceUrl = null)
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(content))
        {
            return "Error: Both title and content are required.";
        }

        var note = new ResearchNote(title, content, sourceUrl, DateTime.UtcNow);
        _notes.Add(note);

        _logger.LogInformation("Note saved: {Title} (total: {Count})", title, _notes.Count);
        return $"Note saved: \"{title}\" (Note #{_notes.Count})";
    }

    [Description("Retrieves all saved research notes. Use this to review what has been gathered before writing a summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"## Research Notes ({_notes.Count} total)\n");

        for (int i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"### Note {i + 1}: {note.Title}");
            sb.AppendLine(note.Content);
            if (!string.IsNullOrEmpty(note.SourceUrl))
            {
                sb.AppendLine($"Source: {note.SourceUrl}");
            }
            sb.AppendLine();
        }

        return sb.ToString();
    }

    [Description("Gets the total count of saved notes.")]
    public string GetNoteCount()
    {
        return $"Total notes saved: {_notes.Count}";
    }

    public IReadOnlyList<ResearchNote> Notes => _notes.AsReadOnly();

    public sealed record ResearchNote(string Title, string Content, string? SourceUrl, DateTime SavedAt);
}

