+using Microsoft.Extensions.Logging;
+
+namespace ResearchAgent.Tools;
+
+/// <summary>
+/// Provides web search capability to the research agent.
+/// Uses the Brave Search API for web queries.
+/// </summary>
+public sealed class WebSearchTool
+{
+    private readonly HttpClient _httpClient;
+    private readonly ILogger<WebSearchTool> _logger;
+
+    public WebSearchTool(HttpClient httpClient, ILogger<WebSearchTool> logger)
+    {
+        _httpClient = httpClient;
+        _logger = logger;
+    }
+
+    [Description("Searches the web for information on a given query. Returns a list of relevant results with titles, URLs, and snippets.")]
+    public async Task<string> SearchWebAsync(
+        [Description("The search query to find information about")] string query,
+        [Description("Maximum number of results to return (1-10)")] int maxResults = 5,
+        CancellationToken cancellationToken = default)
+    {
+        if (string.IsNullOrWhiteSpace(query))
+        {
+            return "Error: Search query cannot be empty.";
+        }
+
+        maxResults = Math.Clamp(maxResults, 1, 10);
+
+        _logger.LogInformation("Searching web for: {Query} (max {MaxResults} results)", query, maxResults);
+
+        try
+        {
+            var apiKey = Environment.GetEnvironmentVariable("BRAVE_SEARCH_API_KEY");
+            if (string.IsNullOrEmpty(apiKey))
+            {
+                return GetSimulatedResults(query, maxResults);
+            }
+
+            var request = new HttpRequestMessage(HttpMethod.Get,
+                $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}");
+            request.Headers.Add("Accept", "application/json");
+            request.Headers.Add("X-Subscription-Token", apiKey);
+
+            var response = await _httpClient.SendAsync(request, cancellationToken);
+            response.EnsureSuccessStatusCode();
+
+            var json = await response.Content.ReadAsStringAsync(cancellationToken);
+            return ParseSearchResults(json, maxResults);
+        }
+        catch (Exception ex)
+        {
+            _logger.LogWarning(ex, "Web search failed, returning simulated results");
+            return GetSimulatedResults(query, maxResults);
+        }
+    }
