using System.ComponentModel;
using System.Text;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capability for the research agent to organize findings.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<ResearchNote> _notes = [];
    private readonly ILogger<NoteTakingTool> _logger;

    public NoteTakingTool(ILogger<NoteTakingTool> logger)
    {
        _logger = logger;
    }

    [Description("Saves a research note with a title and content. Use this to record key findings, facts, and insights discovered during research.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The content of the note containing key findings, facts, or insights")] string content,
        [Description("Optional source URL where the information was found")] string? sourceUrl = null)
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(content))
        {
            return "Error: Both title and content are required.";
        }

        var note = new ResearchNote(title, content, sourceUrl, DateTime.UtcNow);
        _notes.Add(note);

        _logger.LogInformation("Note saved: {Title} (total: {Count})", title, _notes.Count);
        return $"Note saved: \"{title}\" (Note #{_notes.Count})";
    }

    [Description("Retrieves all saved research notes. Use this to review what has been gathered before writing a summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"## Research Notes ({_notes.Count} total)\n");

        for (int i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"### Note {i + 1}: {note.Title}");
            sb.AppendLine(note.Content);
            if (!string.IsNullOrEmpty(note.SourceUrl))
            {
                sb.AppendLine($"Source: {note.SourceUrl}");
            }

            sb.AppendLine();
        }

        return sb.ToString();
    }

    [Description("Gets the total count of saved notes.")]
    public string GetNoteCount()
    {
        return $"Total notes saved: {_notes.Count}";
    }

    public IReadOnlyList<ResearchNote> Notes => _notes.AsReadOnly();

    public sealed record ResearchNote(string Title, string Content, string? SourceUrl, DateTime SavedAt);
}

