using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using OpenAI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddLogging(logging =>
{
    logging.SetMinimumLevel(LogLevel.Information);
    logging.AddConsole();
});

builder.Services.AddHttpClient<WebSearchTool>();
builder.Services.AddSingleton<WebSearchTool>();
builder.Services.AddSingleton<NoteTakingTool>();

// Register the chat client via MEAI abstraction
builder.Services.AddChatClient(chatBuilder =>
{
    var apiKey = builder.Configuration["AI:ApiKey"]
        ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
        ?? throw new InvalidOperationException(
            "OpenAI API key not configured. Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

    var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

    return chatBuilder.UseOpenAIChatClient(modelId, new OpenAIClient(apiKey));
});

var host = builder.Build();

// Resolve services
var chatClient = host.Services.GetRequiredService<IChatClient>();
var webSearchTool = host.Services.GetRequiredService<WebSearchTool>();
var noteTakingTool = host.Services.GetRequiredService<NoteTakingTool>();
var loggerFactory = host.Services.GetRequiredService<ILoggerFactory>();

// Build AI tools from the tool instances
var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTakingTool.SaveNote),
    AIFunctionFactory.Create(noteTakingTool.GetAllNotes),
    AIFunctionFactory.Create(noteTakingTool.GetNoteCount),
};

// Create the research agent with instructions
const string instructions = """
    You are a research agent. Your job is to thoroughly research a topic using web search,
    take organized notes on your findings, and then produce a comprehensive summary.

    Follow this workflow:
    1. Search the web for the topic using multiple relevant queries
    2. For each useful finding, save a note with a descriptive title and the key information
    3. After gathering enough information (at least 3-5 notes), retrieve all notes
    4. Produce a final, well-structured summary of your research findings

    Be thorough but concise. Focus on factual information and cite sources where available.
    """;

var agent = chatClient.AsAIAgent(
    instructions: instructions,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and organizing findings into notes",
    tools: tools,
    loggerFactory: loggerFactory);

// Wrap in a LoopAgent for iteration control
var loopAgent = new LoopAgent(
    agent,
    evaluator: new CompletionMarkerLoopEvaluator(),
    options: new LoopAgentOptions { MaxIterations = 10 },
    loggerFactory: loggerFactory);

// Get the research topic
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent                  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a topic to research: ");
    topic = Console.ReadLine()?.Trim() ?? "artificial intelligence";
}

Console.WriteLine($"\nResearching: {topic}");
Console.WriteLine(new string('─', 50));

// Run the agent
var response = await loopAgent.RunAsync(
    $"Please research the following topic and provide a comprehensive summary: {topic}");

// Output the final response
Console.WriteLine("\n" + new string('═', 50));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('═', 50));
Console.WriteLine();
Console.WriteLine(response.Text);

// Show notes collected
if (noteTakingTool.Notes.Count > 0)
{
    Console.WriteLine("\n" + new string('─', 50));
    Console.WriteLine($"📝 Notes collected: {noteTakingTool.Notes.Count}");
    foreach (var note in noteTakingTool.Notes)
    {
        Console.WriteLine($"  • {note.Title}");
    }
}

